const searchFreshness = `-- name: SearchFreshness :one
SELECT
    COALESCE((SELECT max(indexed_at) FROM workos_index.documents
              WHERE projection_generation = (SELECT generation_id FROM workos_index.active_generation)), 'epoch'::timestamptz)::timestamptz
    AS last_indexed_at
`

func (q *Queries) SearchFreshness(ctx context.Context) (time.Time, error) {
	row := q.db.QueryRow(ctx, searchFreshness)
	var last_indexed_at time.Time
	err := row.Scan(&last_indexed_at)
	return last_indexed_at, err
}

const searchProjectDocuments = `-- name: SearchProjectDocuments :many
WITH q AS (
    SELECT websearch_to_tsquery('simple', $5) AS tsq
),
scored AS (
    SELECT d.source_id, d.source_digest, d.artifact_type, d.title, d.source_created_at, d.content,
           ((CASE WHEN d.title_tsv @@ q.tsq THEN ts_rank(d.title_tsv, q.tsq) ELSE 0.0::double precision END) * 2.0
           + (CASE WHEN d.body_tsv @@ q.tsq THEN ts_rank(d.body_tsv, q.tsq) ELSE 0.0::double precision END))::double precision AS score
    FROM workos_index.documents d, q
    WHERE d.projection_generation = $6
      AND d.owner_user_id = $7
      AND d.project_id = $8
      AND d.tombstoned_at IS NULL
      AND d.indexed_at <= $9
      AND (d.title_tsv @@ q.tsq OR d.body_tsv @@ q.tsq)
)
SELECT source_id, source_digest, artifact_type, title, source_created_at, content, score
FROM scored
WHERE score > 0
  AND (score < $1::double precision
       OR (score = $1::double precision
           AND (source_created_at < $2::timestamptz
                OR (source_created_at = $2::timestamptz
                    AND source_id < $3::uuid))))
ORDER BY score DESC, source_created_at DESC, source_id
LIMIT $4
`

type SearchProjectDocumentsParams struct {
	CursorScore     float64
	CursorCreatedAt time.Time
	CursorSourceID  string
	RowLimit        int32
	QueryText       string
	GenerationID    string
	OwnerUserID     string
	ProjectID       string
	SnapshotThrough time.Time
}

type SearchProjectDocumentsRow struct {
	SourceID        string
	SourceDigest    string
	ArtifactType    string
	Title           string
	SourceCreatedAt time.Time
	Content         string
	Score           float64
}

// Deterministic lexical page (ADR-0013 §5): rank over the built-in 'simple'
// tsquery, title hits weighted 2x, fixed tie-break (score DESC,
// source_created_at DESC, source_id ASC). The cursor triple uses sentinel
// values for the first page (score 1e9). The snapshot watermark excludes
// documents indexed after the chain started, so late arrivals never join an
// open page chain.
func (q *Queries) SearchProjectDocuments(ctx context.Context, arg SearchProjectDocumentsParams) ([]SearchProjectDocumentsRow, error) {
	rows, err := q.db.Query(ctx, searchProjectDocuments,
		arg.CursorScore,
		arg.CursorCreatedAt,
		arg.CursorSourceID,
		arg.RowLimit,
		arg.QueryText,
		arg.GenerationID,
		arg.OwnerUserID,
		arg.ProjectID,
		arg.SnapshotThrough,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchProjectDocumentsRow
	for rows.Next() {
		var i SearchProjectDocumentsRow
		if err := rows.Scan(
			&i.SourceID,
			&i.SourceDigest,
			&i.ArtifactType,
			&i.Title,
			&i.SourceCreatedAt,
			&i.Content,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

